ss="form-control" id="profile-email" type="email" value="<?= e($user['email']) ?>" disabled></div><div class="form-group col-md-6"><label for="phone"><?= e(__('Số điện thoại')) ?></label><input class="form-control" id="phone" name="phone" value="<?= e($old['phone'] ?? $user['phone']) ?>" type="tel" maxlength="20" autocomplete="tel"></div></div><div class="form-group"><label for="avatar"><?= e(__('Ảnh đại diện (JPG, PNG, WebP; tối đa 5 MB)')) ?></label><input class="form-control-file" id="avatar" name="avatar" type="file" accept="image/jpeg,image/png,image/webp"></div><button class="btn btn-primary" type="submit"><?= e(__('Lưu thay đổi')) ?></button></form></section><?php require __DIR__.'/verification.php'; ?><?php if($upcoming): ?><section class="surface-card mt-4"><h2><?= e(__('Chuyến đi sắp tới')) ?></h2><?php foreach(array_slice($upcoming,0,2) as $booking): ?><div class="trip-row"><img src="<?= e(image_url($booking['image_url'])) ?>" alt=""><div><strong><?= e($booking['title']) ?></strong><p><?= e(display_date($booking['check_in'])) ?> → <?= e(display_date($booking['check_out'])) ?></p></div><span class="status status-<?= e($booking['status']) ?>"><?= e(status_label($booking['status'])) ?></span></div><?php endforeach; ?></section><?php endif; ?></div></div></div></section>
